const envelope = $input.first().json;
const payload = envelope.data || envelope.body?.data || envelope.body || envelope;
const projectId = String(payload.project_id || '').trim();
const sources = Array.isArray(payload.sources) ? payload.sources : [];
if (!projectId || !sources.length) throw new Error('BSC source manifest has no enabled RSS or YouTube Channel RSS source');
return sources.map((source) => ({ json: { ...source, project_id: projectId }, pairedItem: { item: 0 } }));

const entries = $input.all();
return entries.flatMap((entry, index) => {
  const source = $('Expand enabled BSC sources').itemMatching(index).json;
  const rawPublishedAt = String(entry.json.isoDate || entry.json.pubDate || '').trim();
  const publishedMs = Date.parse(rawPublishedAt);
  const freshnessHours = Number(source.freshness_hours || 168);
  if (Number.isFinite(publishedMs) && Number.isFinite(freshnessHours) && freshnessHours >= 0 && Date.now() - publishedMs > freshnessHours * 60 * 60 * 1000) return [];
  const text = String(entry.json.content || entry.json.contentSnippet || entry.json.description || '').trim();
  const title = String(entry.json.title || 'Untitled RSS entry').trim();
  const url = String(entry.json.link || entry.json.guid || '').trim();
  if (!url) throw new Error('RSS entry has no canonical URL');
  return [{ json: { project_id: source.project_id, registry_id: source.id, connector_type: source.connector_type, title, url, raw_content: text ? `# ${title}\n\n${text}` : '', lead_only: !text, published_at: Number.isFinite(publishedMs) ? new Date(publishedMs).toISOString() : '', language: source.languages?.[0] || '' }, pairedItem: { item: index } }];
});

const executionId = String($execution.id);
return $input.all().map((entry, index) => {
  const item = entry.json;
  const sequence = String(index);
  if (!item.project_id || !item.registry_id || !item.connector_type) throw new Error('BSC source context is missing from the registered feed item');
  const payload = { schema_version: 'v1', project_id: item.project_id, batch_id: `${item.connector_type}-${executionId}-${item.registry_id}-${sequence}`, execution_id: `${executionId}:${item.registry_id}:${sequence}`, connector_type: item.connector_type, workflow_id: $workflow.id, collected_at: new Date().toISOString(), items: [{ registry_id: item.registry_id, external_id: `${item.url}|${item.published_at || sequence}`, title: item.title, url: item.url, raw_content: item.raw_content || '', published_at: item.published_at || '', language: item.language || '', lead_only: Boolean(item.lead_only), discovery_metrics: { discovery_rank: Number(index) + 1 } }] };
  return { json: { body: JSON.stringify(payload) }, pairedItem: { item: index } };
});

return $input.all().map((entry, index) => {
  const response = entry.json.body || entry.json;
  const data = response.data || {};
  if (!data.batch_id || !Array.isArray(data.receipts)) throw new Error('BSC did not return a valid receipt');
  return { json: { batch_id: data.batch_id, receipt_count: data.receipt_count, replayed: data.replayed, status: data.status }, pairedItem: { item: index } };
});
